  private def renderCompact(value: JsonValue): String = value match {
    case JsonString(v) => s"\"${escape(v)}\""
    case JsonNumber(v) => v.toString
    case JsonBool(v) => if (v) "true" else "false"
    case JsonNull => "null"
    case JsonArray(items) => items.map(renderCompact).mkString("[", ",", "]")
    case JsonObject(fields) =>
      fields.iterator
        .map { case (k, v) => s"\"${escape(k)}\":${renderCompact(v)}" }
        .mkString("{", ",", "}")
  }

  private def renderPretty(value: JsonValue, indent: Int): String = {
