    val padIn = "  " * (indent + 1)

    value match {
      case JsonString(_) | JsonNumber(_) | JsonBool(_) | JsonNull => renderCompact(value)

      case JsonArray(items) if items.isEmpty => "[]"
      case JsonArray(items) =>
        items.map(v => s"$padIn${renderPretty(v, indent + 1)}").mkString("[\n", ",\n", s"\n$pad]")

      case JsonObject(fields) if fields.isEmpty => "{}"
      case JsonObject(fields) =>
        fields.toList
          .sortBy(_._1)
          .map { case (k, v) => s"$padIn\"${escape(k)}\": ${renderPretty(v, indent + 1)}" }
          .mkString("{\n", ",\n", s"\n$pad}")
