    d.bigDecimal.setScale(precision, java.math.RoundingMode.HALF_UP).toPlainString

  override def tokenize(value: Any): Token = ***REDACTED***
    val (strValue, originalType) = value match {
      case bd: BigDecimal => (formatFixed(bd), "BigDecimal")
      case bd: java.math.BigDecimal => (formatFixed(BigDecimal(bd)), "BigDecimal")
      case d: Double => (formatFixed(d), "Double")
      case f: Float => (formatFixed(f.toDouble), "Float")
      case i: Int => (i.toString, "Int")
      case l: Long => (l.toString, "Long")
      case s: Short => (s.toString, "Short")
      case b: Byte => (b.toString, "Byte")
      case other =>
        throw new IllegalArgumentException(s"NumericTokenizer only supports numeric values, got: ${other.getClass.getName}")
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }
}

final class TemporalTokenizer(
  formatStr: Option[String] = None
) extends BaseTokenizer[Any] {

  val ISO_FORMAT: String = "yyyy-MM-dd'T'HH:mm:ss"
  val DATE_FORMAT: String = "yyyy-MM-dd"

  override def tokenize(value: Any): Token = ***REDACTED***
    val formatter = formatStr match {
      case Some(fmt) => DateTimeFormatter.ofPattern(fmt)
      case None =>
        value match {
          case _: LocalDateTime => DateTimeFormatter.ofPattern(ISO_FORMAT)
          case _: LocalDate => DateTimeFormatter.ofPattern(DATE_FORMAT)
          case other =>
            throw new IllegalArgumentException(s"TemporalTokenizer only supports LocalDateTime or LocalDate, got: ${other.getClass.getName}")
        }
    }

    val rendered = value match {
      case dt: LocalDateTime => dt.format(formatter)
      case d: LocalDate => d.format(formatter)
      case other =>
        throw new IllegalArgumentException(s"TemporalTokenizer only supports LocalDateTime or LocalDate, got: ${other.getClass.getName}")
    }

    Token(rendered, TokenType.TEMPORAL)
  }
}

final class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = ***REDACTED*** match {
    case null => Token("NULL", TokenType.NULL)
    case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
    case s: String => stringTokenizer.tokenize(s)
    case bytes: Array[Byte] => stringTokenizer.tokenize(bytes)
    case i: Int => numericTokenizer.tokenize(i)
    case l: Long => numericTokenizer.tokenize(l)
    case f: Float => numericTokenizer.tokenize(f)
    case d: Double => numericTokenizer.tokenize(d)
    case bd: BigDecimal => numericTokenizer.tokenize(bd)
    case bd: java.math.BigDecimal => numericTokenizer.tokenize(bd)
    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate => temporalTokenizer.tokenize(d)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

final class TokenRegistry[A] {
  private val registry: mutable.Map[String, TokenContainer[A]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[A => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[A]): Unit =
    registry.update(key, container)

  def addHandler(handler: A => Option[Token]): Unit =
    handlers += handler

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.toList.map { item =>
          handlers.iterator
            .map(h => h(item))
            .collectFirst { case s @ Some(_) => s }
            .getOrElse(None)
        }
    }
  }
}

// ============================================================================
// Higher-kinded type simulation (implemented idiomatically with Option)
// ============================================================================

class TokenFunctor[+A](val value: Option[A]) {
  def map[B](f: A => B): TokenFunctor[B] = new TokenFunctor(value.map(f))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] =
    value match {
      case Some(a) => f(a)
      case None => new TokenFunctor[B](None)
    }

  def getOrElse[B >: A](default: => B): B = value.getOrElse(default)
}

object TokenFunctor {
  def apply[A](a: A): TokenFunctor[A] = new TokenFunctor(Option(a))
}

final class TokenMonad[+A](override val value: Option[A]) extends TokenFunctor[A](value) {
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] = {
    val out = for {
      f <- funcWrapped.value
      a <- value
    } yield f(a)
    new TokenMonad(out)
  }
}

object TokenMonad {
  def pure[A](a: A): TokenMonad[A] = new TokenMonad(Option(a))
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

sealed trait JsonValue
object JsonValue {
  final case class JsonString(value: String) extends JsonValue
  final case class JsonNumber(value: BigDecimal) extends JsonValue
  final case class JsonBool(value: Boolean) extends JsonValue
  case object JsonNull extends JsonValue
  final case class JsonArray(value: Vector[JsonValue]) extends JsonValue
  final case class JsonObject(value: Map[String, JsonValue]) extends JsonValue
}

private object JsonRenderer {
  import JsonValue._

  private def escape(s: String): String =
    s.flatMap {
      case '"' => "\\\""
      case '\\' => "\\\\"
      case '\b' => "\\b"
      case '\f' => "\\f"
      case '\n' => "\\n"
      case '\r' => "\\r"
      case '\t' => "\\t"
      case c if c.isControl => f"\\u${c.toInt}%04x"
      case c => c.toString
    }

  def render(value: JsonValue, pretty: Boolean): String = {
    if (!pretty) renderCompact(value)
    else renderPretty(value, indent = 0)
  }

  private def renderCompact(value: JsonValue): String = value match {
    case JsonString(v) => s"\"${escape(v)}\""
    case JsonNumber(v) => v.toString
    case JsonBool(v) => if (v) "true" else "false"
    case JsonNull => "null"
    case JsonArray(items) => items.map(renderCompact).mkString("[", ",", "]")
    case JsonObject(fields) =>
      fields.iterator
        .map { case (k, v) => s"\"${escape(k)}\":${renderCompact(v)}" }
        .mkString("{", ",", "}")
  }

  private def renderPretty(value: JsonValue, indent: Int): String = {
    val pad = "  " * indent
    val padIn = "  " * (indent + 1)

    value match {
      case JsonString(_) | JsonNumber(_) | JsonBool(_) | JsonNull => renderCompact(value)

      case JsonArray(items) if items.isEmpty => "[]"
      case JsonArray(items) =>
        items.map(v => s"$padIn${renderPretty(v, indent + 1)}").mkString("[\n", ",\n", s"\n$pad]")

      case JsonObject(fields) if fields.isEmpty => "{}"
      case JsonObject(fields) =>
        fields.toList
          .sortBy(_._1)
          .map { case (k, v) => s"$padIn\"${escape(k)}\": ${renderPretty(v, indent + 1)}" }
          .mkString("{\n", ",\n", s"\n$pad}")
    }
  }
}

final class JsonTokenizer(val pretty: Boolean = false) {
  import JsonValue._

  def tokenize(value: JsonValue): Token = ***REDACTED***
    val jsonStr = JsonRenderer.render(value, pretty)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList.filter(_.nonEmpty)

    val resolved: Option[JsonValue] = parts.foldLeft(Option(value)) {
      case (Some(current), part) =>
        current match {
          case JsonObject(fields) => fields.get(part)
          case JsonArray(items) if part.forall(_.isDigit) =>
            val idx = part.toInt
            items.lift(idx)
          case _ => None
        }
      case (None, _) => None
    }

    resolved.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    val stripped =
      if (!stripPunctuation) word
      else word.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse

    val cased = if (lowercase) stripped.toLowerCase else stripped

    if (cased.length < minLength) None
    else {
      val bounded = maxLength match {
        case Some(m) if cased.length > m => cased.take(m)
        case _ => cased
      }
      Option(bounded).filter(_.nonEmpty)
    }
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (w, i) =>
      processToken(w).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> w)
        )
      }
    }
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)

    var currentPos = 0
    val out = mutable.ListBuffer.empty[(String, Int, Int)]

    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        out += ((processed, start, end))
      }

      currentPos = end
    }

    out.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[A] {
  private val normalizers: mutable.ListBuffer[String => String] = mutable.ListBuffer.empty
  private val validators: mutable.ListBuffer[A => Boolean] = mutable.ListBuffer.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[A] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: A => Boolean): TokenizerBuilder[A] = {
    validators += validator
    this
  }

  def withMetadata(kvs: (String, Any)*): TokenizerBuilder[A] = {
    metadata = metadata ++ kvs.toMap
    this
  }

  def build(): A => Token = ***REDACTED***
    val ns = normalizers.toList
    val vs = validators.toList
    val meta = metadata

    (value: A) => {
      vs.foreach { v =>
        if (!v(value)) throw new IllegalArgumentException(s"Validation failed for $value")
      }

      val normalized = ns.foldLeft(value.toString) { case (acc, n) => n(acc) }
      Token(normalized, TokenType.STRING, meta)
    }
  }
}

